import json, re, os
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
from openai import OpenAI

client=OpenAI(api_key=os.environ['BAILIAN_API_KEY'], base_url='https://dashscope.aliyuncs.com/compatible-mode/v1', timeout=180)

def extract_final_answer(text):
    text=(text or '').strip()
    try:
        d=json.loads(text)
        if isinstance(d,dict) and 'final_answer' in d: return str(d['final_answer'])
    except Exception: pass
    m=re.search(r"\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}", text)
    if m:
        try:
            d=json.loads(m.group())
            if isinstance(d,dict) and 'final_answer' in d: return str(d['final_answer'])
        except Exception: pass
    return text

def parse_charges(text):
    text=extract_final_answer(text).strip()
    m=re.search(r"\[罪名\](.*?)(?:<eoa>|$)", text)
    if m: text=m.group(1).strip()
    elif '罪名:' in text: text=text.split('罪名:')[-1]
    text=re.sub(r"<eoa>.*","",text).strip()
    for sep in [';','；',',','，','、']:
        if sep in text: return {p.strip() for p in text.split(sep) if p.strip()}
    return {text} if text else set()

def lawbench_correct(pred,target): return parse_charges(pred)==parse_charges(target)

def uspto_correct(pred,target):
    f=lambda s:{p.strip().lower() for p in extract_final_answer(s).strip().split('.') if p.strip()}
    return f(pred)==f(target)

def s2d_correct(pred,target):
    text=extract_final_answer(pred)
    m=re.search(r"\[DIAGNOSIS\](.*?)\[/DIAGNOSIS\]", text, re.I|re.S)
    if m: text=m.group(1).strip()
    else:
        m=re.search(r"(?:diagnosis|final diagnosis|conclusion)[:：]\s*([^\n]+)", text, re.I)
        if m: text=m.group(1).strip()
    def norm(v):
        v=v.lower().strip(); v=re.sub(r"\s+"," ",v); return re.sub(r"[.!?]+$","",v)
    return norm(text)==norm(target)

def call(messages, max_tokens=16384):
    r=client.chat.completions.create(model='qwen3.7-flash', temperature=0.0, max_tokens=max_tokens,
        messages=messages, extra_body={'enable_thinking': True})
    return r.choices[0].message.content or ''
