    before=sum(grade(task,r['before'],r['target']) for r in sub)
    after=sum(grade(task,r['after'],r['target']) for r in sub)
    print('%-16s n=%2d before=%2d after=%2d  net=%+d'%(task,len(sub),before,after,after-before))
