import answer_space as A, adjudication as J
from concurrent.futures import ThreadPoolExecutor

MEM='/workspace/runs/84ec2cc228a15743611ceb178336561ddcb30aaa/{}/memory.json'

class Model:
    def invoke(self, prompt):
        class Reply: pass
        r=Reply(); r.content=L.call([{'role':'user','content':prompt}], max_tokens=8192)
        return r

def raw_message(task, idx, s):
    d=json.load(open(f'/workspace/runs/84ec2cc228a15743611ceb178336561ddcb30aaa/{task}/conversations/{idx:04d}/sample-{s}.json'))
    msgs=[m for m in d['messages'] if m.get('role')=='assistant' and m.get('content')]
    if not msgs: return None
    c=msgs[-1]['content']
    if isinstance(c,list): c=' '.join(b.get('text','') if isinstance(b,dict) else str(b) for b in c)
    return c

def pick(task, wrong_n, correct_n, seed=7):
    rs=B.samples(task); rng=random.Random(seed)
    bad=[r for r in rs if not r['was_correct'] and r['status']=='ok']
    good=[r for r in rs if r['was_correct']]
    rng.shuffle(bad); rng.shuffle(good)
    return bad[:wrong_n]+good[:correct_n]

def grade(task, pred, target):
    if task=='LawBench': return L.lawbench_correct(pred,target)
    if task=='USPTO': return L.uspto_correct(pred,target)
    return L.s2d_correct(pred,target)

def run_one(task, r):
    text=raw_message(task,r['example_index'],r['sample_index'])
    if text is None: return dict(task=task,ex=r['example_index'],s=r['sample_index'],err='no-assistant')
    model=Model()
    index=A.build_index(MEM.format(task))
    spellings=A.vocabulary(MEM.format(task))
    problem=B.input_text_of(task,r['example_index'],r['sample_index'])
    try:
        adjudicated, applied = J.adjudicate(text, model, problem, index[0], spellings)
    except Exception as e:
        return dict(task=task,ex=r['example_index'],s=r['sample_index'],err='adjudicate:'+str(e)[:60])
    try:
        grounded, subs = A.canonicalize(adjudicated, index)
    except Exception as e:
        return dict(task=task,ex=r['example_index'],s=r['sample_index'],err='canonicalize:'+str(e)[:60])
    return dict(task=task,ex=r['example_index'],s=r['sample_index'],err=None,target=r['target'],
                recorded=r['prediction'], before=L.extract_final_answer(text), after=L.extract_final_answer(grounded),
                applied=applied, subs=subs)

jobs=[]
for task,wn,cn in [('LawBench',56,44),('USPTO',0,24),('Symptom2Disease',13,15)]:
    for r in pick(task,wn,cn): jobs.append((task,r))
print('jobs',len(jobs),flush=True)
with ThreadPoolExecutor(max_workers=10) as ex:
    results=list(ex.map(lambda t: run_one(*t), jobs))
json.dump(results, open('/tmp/an/dryrun_results.json','w'), ensure_ascii=False)
stats=collections.Counter()
for r in results:
    if r['err']: stats[(r['task'],'ERR:'+r['err'][:20])]+=1; continue
    b=grade(r['task'],r['before'],r['target']); a=grade(r['task'],r['after'],r['target'])
    if b!=a: stats[(r['task'],f'{b}->{a}')]+=1
    if r['recorded']!=r['before']: stats[(r['task'],'recorded!=recomputed')]+=1
for k,v in sorted(stats.items(), key=lambda x: str(x)): print(k,v)
for task in ['LawBench','USPTO','Symptom2Disease']:
    sub=[r for r in results if r['task']==task and not r['err']]
    before=sum(grade(task,r['before'],r['target']) for r in sub); after=sum(grade(task,r['after'],r['target']) for r in sub)
    changed=sum(1 for r in sub if r['before']!=r['after']); rew=sum(r['applied'] for r in sub)
    print('%-16s n=%3d before=%3d after=%3d net=%+d | messages changed=%d | rewrites applied=%d'%(task,len(sub),before,after,after-before,changed,rew))
